package com.example.minicommerce.shared.security;
import com.example.minicommerce.shared.error.ErrorCode;import com.fasterxml.jackson.databind.ObjectMapper;import jakarta.servlet.http.*;import java.io.IOException;import java.util.Map;import org.slf4j.MDC;import org.springframework.http.MediaType;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.AuthenticationException;import org.springframework.security.web.*;import org.springframework.stereotype.Component;
@Component public class ApiSecurityHandlers implements AuthenticationEntryPoint,AccessDeniedHandler{private final ObjectMapper json;public ApiSecurityHandlers(ObjectMapper j){json=j;}@Override public void commence(HttpServletRequest req,HttpServletResponse res,AuthenticationException ex)throws IOException{write(res,401,ErrorCode.AUTHENTICATION_FAILED,"需要有效登录凭证");}@Override public void handle(HttpServletRequest req,HttpServletResponse res,AccessDeniedException ex)throws IOException{write(res,403,ErrorCode.ACCESS_DENIED,"没有执行该操作的权限");}private void write(HttpServletResponse res,int status,ErrorCode code,String message)throws IOException{res.setStatus(status);res.setContentType(MediaType.APPLICATION_JSON_VALUE);json.writeValue(res.getOutputStream(),Map.of("code",code.name(),"message",message,"traceId",String.valueOf(MDC.get("traceId"))));}}
